// node testdata/oao_a11y_test.js static/oao.js
const assert = require('node:assert/strict');
const {install,load,flush} = require('./event_dom');
const {doc,create,key} = install();
const columns=[{name:'id',label:'ID',sortable:true}];
const actions=[{key:'edit',label:'Edit',form:[{name:'status',label:'Status',widget:'select',options:{a:'Alpha',b:'Beta'}}]}];
const tables=[{key:'task',label:'Tasks',columns,filters:[{name:'status',label:'Status',widget:'select',op:'in',options:{a:'Alpha',b:'Beta'}}],actions,page_sizes:[20,50,100]}];
const calls=[];
global.fetch=async(url,init)=>{const u=new URL(url,'http://local');calls.push({url:u,method:init.method});return {ok:true,json:async()=>u.pathname.endsWith('/tables')?{tables}:{columns,filters:tables[0].filters,actions,rows:[{id:1}],page:1,size:Number(u.searchParams.get('size'))||20,total:1}};};
const Oao=load(process.argv[2]);
const root=doc.body.appendChild(create('div'));
(async()=>{
    await Oao.render(root,'task');
    let ps=root.querySelector('[data-pagesize]');ps.focus();
    key(ps,'Enter');key(ps,'ArrowDown');key(ps,'ArrowDown');key(ps,'Enter');await flush();
    assert.equal(calls.at(-1).url.searchParams.get('size'),'50','Enter must pick highlighted option');
    assert.equal(doc.querySelector('.oao-select-content').hidden,true);
    ps=root.querySelector('[data-pagesize]');ps.focus();key(ps,'ArrowUp');key(ps,'Enter');await flush();
    assert.equal(calls.at(-1).url.searchParams.get('size'),'100','ArrowUp from closed selects last option');
    let multi=root.querySelector('[data-multiple]');multi.focus();key(multi,'Enter');key(multi,'ArrowDown');key(multi,' ');await flush();
    assert.equal(calls.at(-1).url.searchParams.get('filter[status]'),'a','Space toggles multi-select option');
    let sort=root.querySelector('[data-sort]');
    assert.equal(sort.tagName,'BUTTON','sort uses a native keyboard button');sort.focus();sort.click();await flush();
    assert.equal(calls.at(-1).url.searchParams.get('sort'),'id');
    assert.equal(doc.activeElement,root.querySelector('[data-sort]'),'sort remains focused after the response redraw');
    const trigger=root.querySelector('[data-action]');trigger.focus();trigger.click();await flush();
    const dialog=doc.querySelector('[role="dialog"]'), mask=doc.querySelector('.oao-mask');
    assert.ok(dialog.getAttribute('aria-labelledby'));assert.equal(doc.getElementById(dialog.getAttribute('aria-labelledby')).textContent,'Edit');
    const buttons=dialog.querySelectorAll('button');buttons.at(-1).focus();key(buttons.at(-1),'Tab');
    assert.equal(doc.activeElement,buttons[0],'Tab wraps within the modal');
    key(buttons[0],'Tab',{shiftKey:true});assert.equal(doc.activeElement,buttons.at(-1));
    const outside=doc.body.appendChild(create('button'));outside.focus();
    assert.ok(dialog.contains(doc.activeElement),'programmatic focus outside is constrained');
    const select=dialog.querySelector('[data-form-select]');select.focus();key(select,'Enter');
    const popup=doc.querySelector('.oao-select-content');assert.equal(popup.hidden,false);
    key(select,'ArrowDown');key(select,'ArrowDown');key(select,'Enter');
    assert.equal(dialog.querySelector('input[type="hidden"]').value,'b');
    assert.equal(select.querySelector('.v').textContent,'Beta','a chosen form value must immediately update the visible trigger');
    key(select,'Enter');
    popup.querySelector('[role="option"]').focus();
    assert.ok(popup.contains(doc.activeElement),'dialog-owned popup is allowed by focus constraint');
    key(doc.activeElement,'Escape');assert.equal(popup.hidden,true);assert.equal(mask.classList.contains('open'),true,'first Escape only closes popup');
    key(select,'Escape');await flush();assert.equal(mask.classList.contains('open'),false);assert.equal(doc.activeElement,trigger);
    const page=root.querySelector('[data-page-input]');page.value='bad';key(page,'Enter');
    assert.ok(doc.querySelector('[role="status"]'),'Toast uses a live status region');
    const activeTrigger=root.querySelector('[data-action]');activeTrigger.focus();activeTrigger.click();await flush();
    await Oao.refreshInstance(root); // The original trigger has now been replaced.
    Oao.destroy(root);await flush();
    assert.equal(mask.classList.contains('open'),false,'destroy closes the owned dialog even after its trigger was replaced');
    actions.push({key:'other',label:'Other',form:actions[0].form});
    await Oao.render(root,'task');
    const first=root.querySelector('[data-action="edit"]'),second=root.querySelector('[data-action="other"]');
    first.focus();first.click();await flush();
    let reopen=true;
    first.addEventListener('focusin',()=>{if(reopen){reopen=false;second.click();}});
    dialog.querySelector('.oao-dlg-actions button').click();await flush();
    assert.equal(doc.getElementById(dialog.getAttribute('aria-labelledby')).textContent,'Other');
    dialog.querySelector('.oao-dlg-actions button').click();await flush();
    first.click();await flush();
    assert.equal(mask.classList.contains('open'),true,'focus restoration opening another dialog must still settle the old action');
    Oao.destroy(root);await flush();
    console.log('PASS select keyboard, native sort button, dialog name/focus/owned popup/Escape, and toast live region');
})().catch(e=>{console.error(e);process.exitCode=1;});
